import{_ as h,o as t,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Hoá học","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/hoa-hoc.md","filePath":"ideas/inquiry-ib/hoa-hoc.md"}'),c={name:"ideas/inquiry-ib/hoa-hoc.md"};function a(g,n,e,r,u,l){return t(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="hoa-hoc" tabindex="-1">Hoá học <a class="header-anchor" href="#hoa-hoc" aria-label="Permalink to &quot;Hoá học&quot;">​</a></h1><p>Trên trang này# Hoá học — ba bài học inquiry theo IB <a href="#hoa-hoc-—-ba-bai-hoc-inquiry-theo-ib">​</a> Hoá học có một khó khăn riêng: thứ thật sự xảy ra thì <strong>không nhìn thấy được</strong>. Học sinh thấy bọt khí, thấy đổi màu — nhưng nguyên tử và liên kết thì phải hình dung. Inquiry trong Hoá học chủ yếu là việc bắc cầu giữa cái quan sát được và cái mô hình. Ý xuyên suốt cả mônCái quan sát được — bọt khí, đổi màu, cân nặng — và cái thật sự xảy ra — hạt, liên kết — là hai tầng khác nhau. Hoá học là việc bắc cầu giữa hai tầng đó. Cũng quan trọng — nhưng không phải ý lớn nhất- Một phép đo chỉ có nghĩa khi đã xác định rõ ranh giới của hệ đang đo.</p><ul><li>Phân loại (axit / bazơ, kim loại / phi kim) là công cụ con người đặt ra, không phải ranh giới có sẵn trong tự nhiên.</li><li>Một mô hình tốt giải thích được nhiều hiện tượng khác nhau bằng cùng một ý — đó là dấu hiệu nhận ra nó tốt.</li></ul><h2 id="demo-1-—-bao-toan-khoi-luong-nen-chay-thi-nhe-đi-hay-nang-len-​" tabindex="-1">Demo 1 — Bảo toàn khối lượng: nến cháy thì nhẹ đi hay nặng lên? <a href="#demo-1-—-bao-toan-khoi-luong-nen-chay-thi-nhe-đi-hay-nang-len">​</a> <a class="header-anchor" href="#demo-1-—-bao-toan-khoi-luong-nen-chay-thi-nhe-đi-hay-nang-len-​" aria-label="Permalink to &quot;Demo 1 — Bảo toàn khối lượng: nến cháy thì nhẹ đi hay nặng lên? [​](#demo-1-—-bao-toan-khoi-luong-nen-chay-thi-nhe-đi-hay-nang-len)&quot;">​</a></h2><p><strong>Lớp</strong>8–9<strong>Key concept</strong>Change<strong>Related concepts</strong>Conservation · Evidence · Models<strong>Global context</strong>Scientific and technical innovation<strong>Statement of inquiry</strong>Một phép đo chỉ có nghĩa khi ta xác định rõ ranh giới của hệ đang đo.<strong>Cần biết trước</strong>Chất, phản ứng hoá học, cân điện tử</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Định luật bảo toàn khối lượng phát biểu thế nào?</li><li><strong>Conceptual:</strong> Vì sao có phản ứng làm khối lượng đo được giảm, có phản ứng làm nó tăng?</li><li><strong>Debatable:</strong> Khi kết quả thí nghiệm mâu thuẫn với định luật, ta nên nghi ngờ cái nào trước?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Hai thí nghiệm mâu thuẫn nhau (12 phút).</strong> Nhóm A: đốt một cây nến trên cân, ghi khối lượng theo thời gian. → <strong>Giảm.</strong> Nhóm B: đốt một dải magie trong chén sứ trên cân. → <strong>Tăng.</strong> Giáo viên chỉ hỏi: <em>&quot;Hai nhóm ra hai kết quả ngược nhau. Cả hai cùng đúng được không?&quot;</em><strong>Bước 2 — Để mâu thuẫn tồn tại (8 phút).</strong> Đây là bước mà giáo viên phải kìm mình lại. Học sinh tranh luận, đưa giả thuyết: cân hỏng, magie hút ẩm, nến &quot;biến mất&quot;. Giáo viên chỉ ghi các giả thuyết lên bảng và hỏi: <em>&quot;Kiểm tra giả thuyết này bằng cách nào?&quot;</em><strong>Bước 3 — Thí nghiệm quyết định (15 phút).</strong> Giáo viên đưa ra một biến thể: đốt nến trong một bình kín đã cân trước — cả bình, cả nến, cả không khí bên trong. Kết quả: khối lượng <strong>không đổi</strong>. <em>&quot;Khác gì với lần trước?&quot;</em> Học sinh dần nhận ra: lần trước, khí sinh ra bay đi mất và không được cân. Lần này nó nằm trong bình. <em>&quot;Vậy còn magie? Vì sao nó nặng lên?&quot;</em> Ai đó sẽ đi tới: magie kết hợp với oxi từ không khí — khối lượng oxi được thêm vào chén sứ. <strong>Bước 4 — Khái niệm hệ kín (7 phút).</strong> Giáo viên đưa ngôn ngữ chính xác: hệ kín, hệ hở, định luật bảo toàn khối lượng. Học sinh hiểu định luật này <strong>không phải một điều cần tin</strong>, mà là một điều đúng khi ta đo đúng thứ cần đo. <strong>Bước 5 — Câu hỏi tranh luận (8 phút).</strong><em>&quot;Nếu ngày mai em làm thí nghiệm và khối lượng không bảo toàn, em kết luận gì? Định luật sai, hay thí nghiệm của em có vấn đề? Làm sao biết?&quot;</em> Đây là câu hỏi về <strong>bản chất của khoa học</strong>, và nó chính là thứ môn Theory of Knowledge trong IB dạy — được lồng vào một tiết Hoá học lớp 8.</p><h2 id="demo-2-—-toc-đo-phan-ung-đieu-tra-do-hoc-sinh-tu-thiet-ke-​" tabindex="-1">Demo 2 — Tốc độ phản ứng: điều tra do học sinh tự thiết kế <a href="#demo-2-—-toc-đo-phan-ung-đieu-tra-do-hoc-sinh-tu-thiet-ke">​</a> <a class="header-anchor" href="#demo-2-—-toc-đo-phan-ung-đieu-tra-do-hoc-sinh-tu-thiet-ke-​" aria-label="Permalink to &quot;Demo 2 — Tốc độ phản ứng: điều tra do học sinh tự thiết kế [​](#demo-2-—-toc-đo-phan-ung-đieu-tra-do-hoc-sinh-tu-thiet-ke)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Systems<strong>Related concepts</strong>Interaction · Patterns · Energy<strong>Global context</strong>Scientific and technical innovation<strong>Statement of inquiry</strong>Tốc độ của một quá trình phụ thuộc vào tần suất và năng lượng của các va chạm giữa các thành phần.<strong>Cần biết trước</strong>Phương trình hoá học, mô hình hạt, khái niệm nồng độ</p><h3 id="ba-cau-hoi-​-1" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi-1">​</a> <a class="header-anchor" href="#ba-cau-hoi-​-1" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi-1)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Những yếu tố nào ảnh hưởng tốc độ phản ứng?</li><li><strong>Conceptual:</strong> Vì sao tăng nhiệt độ lại làm phản ứng nhanh hơn?</li><li><strong>Debatable:</strong> Trong công nghiệp, có nên luôn chạy phản ứng ở tốc độ tối đa?</li></ul><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Hiện tượng mở (5 phút).</strong> Hai cốc: viên sủi thả vào nước lạnh và nước nóng. Học sinh bấm giờ. <em>&quot;Kể ra mọi thứ em nghĩ là ảnh hưởng tới tốc độ.&quot;</em> Danh sách của lớp: nhiệt độ · kích thước hạt · lượng nước · khuấy · loại viên. <strong>Bước 2 — Mỗi nhóm điều tra một biến (25 phút).</strong> Đây là phần chính, và giáo viên <strong>không đưa quy trình sẵn</strong>. Mỗi nhóm phải tự trả lời bốn câu trước khi được lấy dụng cụ:</p><ul><li>Em thay đổi cái gì? (biến độc lập)</li><li>Em đo cái gì? (biến phụ thuộc)</li><li>Em phải giữ nguyên những gì? (biến kiểm soát)</li><li>Em lặp lại bao nhiêu lần, và vì sao? Câu 3 là chỗ hầu hết nhóm mắc kẹt lần đầu — và đó chính là bài học. Nhóm điều tra kích thước hạt thường quên giữ nguyên khối lượng; nhóm điều tra nhiệt độ hay quên rằng thể tích nước cũng phải như nhau. Giáo viên đi từng nhóm, chỉ hỏi lại bốn câu đó, không sửa hộ. <strong>Bước 3 — Chia sẻ dữ liệu (10 phút).</strong> Các nhóm dán kết quả lên bảng chung. Cả lớp giờ có dữ liệu về năm biến — nhiều hơn hẳn thứ một nhóm tự làm được. <strong>Bước 4 — Xây mô hình giải thích (15 phút).</strong><em>&quot;Bây giờ giải thích tất cả các kết quả này bằng MỘT ý tưởng duy nhất.&quot;</em> Giáo viên gợi bằng câu hỏi: <em>&quot;Để hai chất phản ứng, chúng phải làm gì với nhau trước đã?&quot;</em> Học sinh dần dựng lên mô hình va chạm: phản ứng xảy ra khi các hạt va vào nhau đủ mạnh. Rồi kiểm tra mô hình đó với từng kết quả:</li><li>Nhiệt độ cao → hạt chuyển động nhanh → va nhiều hơn và mạnh hơn ✓</li><li>Hạt nhỏ → diện tích tiếp xúc lớn → va nhiều hơn ✓</li><li>Nồng độ cao → nhiều hạt hơn trong cùng thể tích → va nhiều hơn ✓ Một mô hình giải thích được cả năm kết quả — học sinh cảm nhận được sức mạnh của một lý thuyết tốt. <strong>Bước 5 — Tranh luận (10 phút).</strong><em>&quot;Nhà máy sản xuất amoniac có thể tăng nhiệt độ để phản ứng nhanh hơn. Vì sao họ không tăng lên thật cao?&quot;</em> Dẫn tới: chi phí năng lượng, an toàn, và — với lớp lớn hơn — cân bằng hoá học.</li></ul><h2 id="demo-3-—-axit-va-bazo-tu-che-chat-chi-thi-​" tabindex="-1">Demo 3 — Axit và bazơ: tự chế chất chỉ thị <a href="#demo-3-—-axit-va-bazo-tu-che-chat-chi-thi">​</a> <a class="header-anchor" href="#demo-3-—-axit-va-bazo-tu-che-chat-chi-thi-​" aria-label="Permalink to &quot;Demo 3 — Axit và bazơ: tự chế chất chỉ thị [​](#demo-3-—-axit-va-bazo-tu-che-chat-chi-thi)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Form<strong>Related concepts</strong>Patterns · Evidence · Consequences<strong>Global context</strong>Identities and relationships<strong>Statement of inquiry</strong>Phân loại là công cụ do con người tạo ra để nhận ra quy luật, và mỗi cách phân loại đều có ranh giới của nó.<strong>Cần biết trước</strong>Dung dịch, khái niệm pH ở mức sơ khởi</p><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Tự làm chất chỉ thị (12 phút).</strong> Học sinh đun bắp cải tím lấy nước. Chất lỏng màu tím sẫm. <em>&quot;Nhỏ nước bắp cải vào từng mẫu này, ghi màu.&quot;</em> Mẫu: giấm · nước chanh · nước máy · nước xà phòng · nước rửa chén · baking soda · nước ngọt có ga · nước muối. <strong>Bước 2 — Phân loại trước khi có tên gọi (10 phút).</strong><em>&quot;Xếp các mẫu thành nhóm dựa trên màu. Em xếp thành mấy nhóm? Vì sao?&quot;</em> Các nhóm thường xếp thành 2 hoặc 3 nhóm. Giáo viên hỏi: <em>&quot;Nhóm khác xếp khác — ai đúng?&quot;</em> Đây là bước có giá trị lớn: học sinh phát hiện ra rằng phân loại là <strong>quyết định của người phân loại</strong>, và ranh giới không tự nhiên có sẵn. <strong>Bước 3 — Xây thang đo (12 phút).</strong><em>&quot;Xếp các mẫu thành một dãy từ đầu này sang đầu kia, theo màu.&quot;</em> Học sinh tự tạo ra một thang liên tục. Lúc này giáo viên mới đưa thang pH và giải thích các con số — và học sinh thấy nó chỉ là phiên bản chính xác hơn của thứ mình vừa làm. <strong>Bước 4 — Kiểm chứng (10 phút).</strong> So thang tự làm với giấy quỳ chuẩn. Chỗ nào khớp, chỗ nào lệch? <em>&quot;Chất chỉ thị của em có nhược điểm gì so với giấy quỳ?&quot;</em><strong>Bước 5 — Mở rộng ra đời sống (10 phút).</strong><em>&quot;Vì sao đất trồng cần đúng pH? Vì sao nước mưa axit là vấn đề? Vì sao dạ dày cần axit mạnh mà thực quản thì không chịu được?&quot;</em> Làm được ở nhà Demo 3 làm được hoàn toàn trong bếp: một cái bắp cải tím và vài thứ có sẵn. Đây là hoạt động khoa học có tỷ lệ &quot;công sức bỏ ra / ấn tượng để lại&quot; tốt nhất mà chúng tôi biết cho lứa 8–12 tuổi. Điều quan trọng: <strong>đừng nói trước kết quả</strong>. Để con đoán màu sẽ ra sao trước mỗi lần nhỏ. <a href="/ideas/inquiry-ib/sinh-hoc">Sinh học →</a></p>',20)])])}const b=h(c,[["render",a]]);export{s as __pageData,b as default};
